select ac_cargar_fuente($ac${"slug":"protocolo-fauna-cba","titulo":"Qué hacer si encontrás fauna silvestre","organizacion":"Secretaría de Ambiente de Córdoba","url":"https://ambiente.cba.gov.ar/que-debes-hacer-si-encontras-fauna-silvestre/","publicado":"2024","licencia":"Documento público","contenido":"Ante un animal silvestre herido: no manipularlo sin protección, no darle agua ni comida, colocarlo en una caja de cartón ventilada, oscura y silenciosa, no exhibirlo ni fotografiarlo de cerca, no intentar criarlo, y contactar a la autoridad de fauna. La mayoría de los pichones encontrados en el suelo son volantones que todavía reciben alimento de sus padres: corresponde dejarlos donde están o subirlos a una rama cercana."}$ac$::jsonb);
