select ac_cargar_fuente($ac${"slug":"huella-hidrica","titulo":"Qué es y cómo se mide la huella hídrica","organizacion":"Water Footprint Network","url":"https://www.waterfootprint.org/","publicado":"2024","licencia":"Uso con atribución","contenido":"La huella hídrica se divide en verde (agua de lluvia almacenada en el suelo y consumida por los cultivos), azul (agua superficial y subterránea consumida) y gris (agua necesaria para diluir la contaminación generada). El agua virtual es el agua utilizada para producir un bien, incorporada en él aunque no se vea. Producir un kilo de carne vacuna requiere del orden de 15.000 litros de agua contando toda la cadena; una remera de algodón, alrededor de 2.700 litros."}$ac$::jsonb);
select ac_cargar_fuente($ac${"slug":"ipcc-ar6","titulo":"IPCC Sixth Assessment Report (AR6)","organizacion":"IPCC","url":"https://www.ipcc.ch/assessment-report/ar6/","publicado":"2021-2023","licencia":"Uso con atribución","contenido":"El efecto invernadero natural mantiene la Tierra habitable; el problema es su intensificación por el aumento de gases de efecto invernadero de origen humano. Los principales son dióxido de carbono, metano, óxido nitroso y gases fluorados. El metano tiene un potencial de calentamiento global mucho mayor que el CO₂ en un horizonte de 100 años, pero permanece menos tiempo en la atmósfera. Una fracción importante del CO₂ emitido permanece en la atmósfera durante siglos."}$ac$::jsonb);
