select ac_cargar_fuente($ac${"slug":"yale-reciclaje","titulo":"Recycling isn’t the solution to the climate crisis","organizacion":"Yale Climate Connections","url":"https://yaleclimateconnections.org/2024/09/recycling-isnt-the-solution-to-the-climate-crisis/","publicado":"2024","licencia":"Uso con atribución","contenido":"El reciclado es la tercera opción, después de evitar y de reducir. La mayor parte del plástico producido en la historia nunca fue reciclada, y el plástico pierde calidad en cada ciclo de reciclado, por lo que la reducción y el rediseño pesan más que el reciclado."}$ac$::jsonb);
